import { useState } from 'react';
import { type Project, measure } from './task-tree.js';
import { ProgressBar } from './progress-bar.js';
import styles from './trellis-app.module.css';

const COLORS = ['#7c5cff', '#ff5c7a', '#2bb3ff', '#ffb020', '#22c55e', '#e05cff'];

/**
 * Sidebar listing projects with their overall progress and a form to create new ones.
 * @param props.projects - all projects
 * @param props.activeId - selected project id
 * @param props.onSelect - selects a project
 * @param props.onCreate - creates a project
 */
export function ProjectSidebar({
  projects,
  activeId,
  onSelect,
  onCreate,
}: {
  projects: Project[];
  activeId?: string;
  onSelect: (id: string) => void;
  onCreate: (v: { name: string; description: string; color: string }) => void;
}) {
  const [name, setName] = useState('');
  const [description, setDescription] = useState('');
  const [color, setColor] = useState(COLORS[0]);
  const [open, setOpen] = useState(false);

  return (
    <aside className={styles.sidebar}>
      <div className={styles.brand}>
        <span className={styles.logo}>⌗</span> Trellis
      </div>
      <div className={styles.sideLabel}>Projects</div>
      <ul className={styles.projectList}>
        {projects.map((p) => {
          const m = measure(p.tasks);
          return (
            <li key={p.id}>
              <button
                className={`${styles.projectItem} ${p.id === activeId ? styles.projectItemActive : ''}`}
                onClick={() => onSelect(p.id)}
              >
                <span className={styles.projectItemTop}>
                  <span className={styles.dot} style={{ background: p.color }} />
                  <span className={styles.projectItemName}>{p.name}</span>
                  <span className={styles.projectItemPct}>{m.percent}%</span>
                </span>
                <ProgressBar percent={m.percent} color={p.color} />
              </button>
            </li>
          );
        })}
      </ul>

      {open ? (
        <form
          className={styles.taskForm}
          onSubmit={(e) => {
            e.preventDefault();
            if (!name.trim()) return;
            onCreate({ name: name.trim(), description: description.trim(), color });
            setName('');
            setDescription('');
            setOpen(false);
          }}
        >
          <input autoFocus className={styles.input} placeholder="Project name" value={name} onChange={(e) => setName(e.target.value)} />
          <input className={styles.input} placeholder="Description (optional)" value={description} onChange={(e) => setDescription(e.target.value)} />
          <div className={styles.swatches}>
            {COLORS.map((c) => (
              <button
                type="button"
                key={c}
                aria-label={`Color ${c}`}
                className={`${styles.swatch} ${c === color ? styles.swatchActive : ''}`}
                style={{ background: c }}
                onClick={() => setColor(c)}
              />
            ))}
          </div>
          <div className={styles.formButtons}>
            <button type="button" className={styles.ghostBtn} onClick={() => setOpen(false)}>Cancel</button>
            <button type="submit" className={styles.primaryBtn} disabled={!name.trim()}>Create</button>
          </div>
        </form>
      ) : (
        <button className={styles.newProject} onClick={() => setOpen(true)}>+ New project</button>
      )}
    </aside>
  );
}
